    private DatePicker trainDatePicker() { DatePicker picker=new DatePicker(selectedTrainJourneyDate);DateTimeFormatter format=DateTimeFormatter.ofPattern("dd/MM/yyyy");picker.setEditable(true);picker.setPromptText("dd/MM/yyyy");picker.setConverter(new StringConverter<>() { @Override public String toString(LocalDate value) { return value == null ? "" : format.format(value); } @Override public LocalDate fromString(String value) { return value == null || value.isBlank() ? null : LocalDate.parse(value.trim(),format); } });picker.valueProperty().addListener((observable,oldDate,newDate)->{if(newDate!=null)selectedTrainJourneyDate=newDate;});return picker; }
