    private Node travellerDetailsPage(){int count=travellerCount();TextField contactName=new TextField(primaryContactDraft==null?"":primaryContactDraft.fullName());TextField contactMobile=new TextField(primaryContactDraft==null?"":primaryContactDraft.mobileNumber());TextField contactEmail=new TextField(primaryContactDraft==null?"":primaryContactDraft.emailAddress());TextField emergency=new TextField(emergencyContactDraft);TextArea notes=new TextArea(assistanceNotesDraft);notes.setPrefRowCount(2);GridPane contactGrid=new GridPane();contactGrid.setHgap(8);contactGrid.setVgap(6);contactGrid.add(text("Full Name","custom-group-title"),0,0);contactGrid.add(text("Mobile Number","custom-group-title"),1,0);contactGrid.add(text("Email Address","custom-group-title"),2,0);contactGrid.add(contactName,0,1);contactGrid.add(contactMobile,1,1);contactGrid.add(contactEmail,2,1);contactGrid.add(text("Emergency Contact Number (optional)","custom-group-title"),0,2);contactGrid.add(text("Special Assistance / Notes (optional)","custom-group-title"),1,2,2,1);contactGrid.add(emergency,0,3);contactGrid.add(notes,1,3,2,1);VBox contactCard=travellerCard("Primary Contact",contactGrid);VBox travellerCards=new VBox(8);List<TravellerForm> forms=new ArrayList<>();for(int i=0;i<count;i++){TravellerForm form=travellerForm(i+1,i<travellerDrafts.size()?travellerDrafts.get(i):null);forms.add(form);travellerCards.getChildren().add(form.card());}Label error=text("","custom-form-error");clearErrorOnEdit(error,contactName,contactMobile,contactEmail,emergency,notes);for(TravellerForm form:forms){clearErrorOnEdit(error,form.name(),form.age(),form.idNumber());clearErrorOnEdit(error,form.gender(),form.idType());}Button back=new Button("Back to Review");back.getStyleClass().add("package-secondary-button");back.setOnAction(e->{travellerDetailsOpen=false;render();});Button next=new Button("Continue to Booking Summary");next.getStyleClass().add("package-search-button");next.setOnAction(e->{PackageBookingDraft draft=validateTravellerDraft(contactName,contactMobile,contactEmail,emergency,notes,forms,error);if(draft!=null){bookingDraft=draft;primaryContactDraft=draft.primaryContact();travellerDrafts=draft.travellers();emergencyContactDraft=draft.emergencyContact();assistanceNotesDraft=draft.specialAssistanceNotes();travellerDetailsOpen=false;bookingSummaryOpen=true;render();}});HBox actions=new HBox(10,back,spacer(),next);VBox page=new VBox(10,text("Traveller Details","custom-section-title"),text("Provide primary contact and traveller information for this local draft. No booking, KYC, payment, or external verification is performed.","custom-help"),contactCard,text("Travellers ("+count+")","custom-group-title"),travellerCards,error,actions);page.getStyleClass().add("traveller-details-page");return page;}
    private TravellerForm travellerForm(int number,PackageTraveller saved){TextField name=new TextField(saved==null?"":saved.fullName());TextField age=new TextField(saved==null?"":Integer.toString(saved.age()));ComboBox<String> gender=new ComboBox<>();gender.getItems().addAll("Male","Female","Other / Prefer not to say");gender.setValue(saved==null?null:saved.gender());ComboBox<String> idType=new ComboBox<>();idType.getItems().addAll("Aadhaar","Passport","Driving Licence","Voter ID","Other");idType.setValue(saved==null?null:saved.idType());TextField idNumber=new TextField(saved==null?"":saved.idNumber());GridPane grid=new GridPane();grid.setHgap(8);grid.setVgap(6);grid.add(text("Full Name","custom-group-title"),0,0);grid.add(text("Age","custom-group-title"),1,0);grid.add(text("Gender","custom-group-title"),2,0);grid.add(text("ID Type","custom-group-title"),3,0);grid.add(text("ID Number","custom-group-title"),4,0);grid.add(name,0,1);grid.add(age,1,1);grid.add(gender,2,1);grid.add(idType,3,1);grid.add(idNumber,4,1);return new TravellerForm(travellerCard("Traveller "+number,grid),name,age,gender,idType,idNumber);}
    private VBox travellerCard(String title,Node content){VBox card=new VBox(8,text(title,"custom-review-card-title"),content);card.getStyleClass().add("traveller-form-card");return card;}
    private PackageBookingDraft validateTravellerDraft(TextField contactName,TextField contactMobile,TextField contactEmail,TextField emergency,TextArea notes,List<TravellerForm> forms,Label error){String name=contactName.getText().trim(),mobile=contactMobile.getText().trim(),email=contactEmail.getText().trim();if(name.isBlank()){error.setText("Enter the primary contact's full name.");return null;}if(!mobile.matches("[6-9][0-9]{9}")){error.setText("Enter a valid 10-digit Indian mobile number.");return null;}if(!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")){error.setText("Enter a valid email address.");return null;}List<PackageTraveller> travellers=new ArrayList<>();for(int i=0;i<forms.size();i++){TravellerForm form=forms.get(i);String travellerName=form.name().getText().trim(),ageText=form.age().getText().trim(),type=form.idType().getValue(),id=form.idNumber().getText().trim();int age;try{age=Integer.parseInt(ageText);}catch(NumberFormatException ex){error.setText("Enter a valid age for Traveller "+(i+1)+".");return null;}if(travellerName.isBlank()||age<1||age>120||form.gender().getValue()==null||type==null||id.isBlank()){error.setText("Complete all required fields for Traveller "+(i+1)+".");return null;}if("Aadhaar".equals(type)&&!id.matches("[0-9]{12}")){error.setText("Aadhaar for Traveller "+(i+1)+" must be 12 digits. This is format validation only.");return null;}travellers.add(new PackageTraveller(travellerName,age,form.gender().getValue(),type,id));}return new PackageBookingDraft(pkg.id(),travellerSnapshot,new PrimaryContact(name,mobile,email),List.copyOf(travellers),emergency.getText().trim(),notes.getText().trim(),travellerSnapshot.totalAmount(),Instant.now());}
    private int travellerCount(){return state.trainSearch()==null?1:Math.max(1,Math.min(10,state.trainSearch().travellers()));}
    private Node bookingSummaryShell(){if(bookingDraft==null){bookingSummaryOpen=false;travellerDetailsOpen=true;return travellerDetailsPage();}VBox left=new VBox(8,text("Booking Summary","custom-section-title"),bookingPackageCard(),bookingContactCard(),bookingTravellersCard(),bookingCustomizationCard(),bookingPriceCard());CheckBox terms=new CheckBox("I have reviewed the package, traveller details, cancellation terms and package conditions.");terms.getStyleClass().add("booking-terms");Label paymentMessage=text(paymentResult==null?"":paymentResult.message(),"custom-form-error");Button back=new Button("Back to Traveller Details");back.getStyleClass().add("package-secondary-button");back.setOnAction(e->{bookingSummaryOpen=false;travellerDetailsOpen=true;render();});Button proceed=new Button("Proceed to Payment");proceed.getStyleClass().add("package-search-button");proceed.setDisable(true);terms.selectedProperty().addListener((o,oldValue,selected)->proceed.setDisable(!selected));proceed.setOnAction(e->preparePayment(proceed,paymentMessage));HBox actions=new HBox(10,back,spacer(),proceed);left.getChildren().addAll(terms,paymentMessage,actions);left.getStyleClass().add("booking-summary-left");return left;}
    private Node demoPaymentSuccessPage(){if(bookingDraft==null){demoPaymentSuccessOpen=false;bookingSummaryOpen=true;return bookingSummaryShell();}VBox details=new VBox(5,reviewLine("Package",pkg.title()),reviewLine("Route",pkg.origin()+" → Nashik"),reviewLine("Travellers",Integer.toString(bookingDraft.travellers().size())),reviewLine("Amount",money(bookingDraft.totalAmount())),reviewLine("Payment Status","Test Payment — Not Razorpay Verified"),reviewLine("Payment Mode","Test Payment"));Label saveMessage=text(demoBookingMessage,"custom-form-error");VBox page=new VBox(10,text("Payment Step Completed","custom-section-title"),text("Payment verification is pending.","custom-help"),bookingCard("Payment Step",details),text("Real payment gateway verification will be enabled with Razorpay integration.","custom-help"));Button back=new Button("Back to Booking Summary");back.getStyleClass().add("package-secondary-button");back.setDisable(demoBookingSaving);back.setOnAction(e->{demoPaymentSuccessOpen=false;bookingSummaryOpen=true;render();});Button confirm=new Button("Confirm Booking");confirm.getStyleClass().add("package-search-button");confirm.setDisable(demoBookingSaving);confirm.setOnAction(e->confirmDemoBooking(confirm,saveMessage));HBox actions=new HBox(10,back,spacer(),confirm);page.getChildren().addAll(saveMessage,actions);page.getStyleClass().add("booking-summary-left");return page;}
    private void confirmDemoBooking(Button confirm,Label message){if(demoBookingSaving){return;}if(confirmedPackageBooking!=null){demoPaymentSuccessOpen=false;bookingConfirmationOpen=true;render();return;}AppSession.User user=AppSession.currentUser();if(user==null){message.setText("Please login before confirming the booking.");return;}if(bookingDraft==null){message.setText("A valid booking draft is required.");return;}if(pendingPackageBooking==null)pendingPackageBooking=PackageBooking.confirmedTest(user.uid(),pkg.title(),pkg.origin()+" → Nashik",pkg.duration(),bookingDraft);demoBookingSaving=true;confirm.setDisable(true);message.setText("Saving booking...");packageBookingRepository.save(pendingPackageBooking,user.idToken()).whenComplete((saved,error)->Platform.runLater(()->{demoBookingSaving=false;if(error!=null){LOGGER.warning("Kumbh package booking persistence failed: "+bookingPersistenceError(error));message.setText("Booking could not be saved. Please try again.");confirm.setDisable(false);return;}confirmedPackageBooking=saved;demoPaymentSuccessOpen=false;bookingConfirmationOpen=true;render();}));}
    private String bookingPersistenceError(Throwable error){Throwable cause=error;while(cause.getCause()!=null)cause=cause.getCause();String message=cause.getMessage();return message==null||message.isBlank()?cause.getClass().getSimpleName():message.replaceAll("[\\r\\n]+"," ");}
